def backfill_occurrences(apps, schema_editor):
    """Seed one occurrence per existing issue, from its current batch FK.

    That FK records only the MOST RECENT sighting, so earlier sightings are
    already lost and cannot be recovered — this preserves what remains rather
    than starting empty, which would blank every historical batch's issue list
    outright. Sightings accumulate correctly from here.
    """
    Issue = apps.get_model('Data', 'Issue')
    IssueOccurrence = apps.get_model('Data', 'IssueOccurrence')

    rows = []
    qs = Issue.objects.exclude(batch__isnull=True).values('id', 'batch_id', 'severity')
    for row in qs.iterator(chunk_size=2000):
        rows.append(IssueOccurrence(
            issue_id=row['id'], batch_id=row['batch_id'], severity=row['severity'],
        ))
        if len(rows) >= 2000:
            IssueOccurrence.objects.bulk_create(rows, ignore_conflicts=True)
            rows = []
    if rows:
        IssueOccurrence.objects.bulk_create(rows, ignore_conflicts=True)


